package fraymus.workspace;

import org.json.*;
import java.awt.image.BufferedImage;
import java.nio.*;
import java.nio.channels.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;

/** Private originals and immutable measured registration/trial history; no native write interface. */
final class Alignment041Store {
    static final String VERSION="measured-alignment-041-v1";
    private final Path root,file;private final WorldLedger worlds;private final Map<String,Engine> engines=new HashMap<>();
    private final LinkedHashMap<String,JSONObject> snapshots=new LinkedHashMap<>();private final Set<String> pins=new HashSet<>();
    private record Engine(MatTarget041 tracker,TabletopFilter filter,MatReferenceGuard reference,PlaneCalibration plane){}
    Alignment041Store(Path project,WorldLedger worlds)throws Exception{root=project.resolve("alignment-041");file=root.resolve("state.json");this.worlds=worlds;access(true,s->{for(Object raw:s.getJSONArray("trials")){var t=(JSONObject)raw;if(t.getString("status").equals("running"))t.put("status","interrupted").put("reason","App ended; original prefix preserved. New camera session requires a new explicit trial.");}return null;});}
    static String identity(){var b=new StringBuilder(VERSION);for(Class<?> c:new Class<?>[]{Alignment041Store.class,MatRegistration041.class,MatTarget041.class,MatTrials041.class,TabletopFilter.class,MatReferenceGuard.class,PlaneCalibration.class,PixelTracker.class,WorldFrames.class})try(var in=c.getResourceAsStream(c.getSimpleName()+".class")){b.append(PerceptionStore.hash(in.readAllBytes()));}catch(Exception e){throw new IllegalStateException(e);}return MeasurementStore.hash(b.toString());}
    private interface Tx<T>{T apply(JSONObject s)throws Exception;}
    private synchronized <T>T access(boolean write,Tx<T> fn)throws Exception{Files.createDirectories(root);try(var ch=FileChannel.open(root.resolve("state.lock"),StandardOpenOption.CREATE,StandardOpenOption.WRITE);var held=ch.lock()){JSONObject s;if(Files.exists(file)){if(Files.size(file)>32_000_000)throw new IllegalStateException("Alignment history limit reached; originals preserved");var e=new JSONObject(Files.readString(file));s=e.getJSONObject("payload");if(!VERSION.equals(e.getString("version"))||!WorldFrames.hash(s).equals(e.getString("sha256")))throw new IllegalStateException("Alignment history checksum differs; original preserved");}else s=new JSONObject().put("registrations",new JSONArray()).put("trials",new JSONArray()).put("selectedRegistrationId","").put("selectedTrialId","");T result=fn.apply(s);if(write){if(s.getJSONArray("registrations").length()>32||s.getJSONArray("trials").length()>24)throw new IllegalStateException("Alignment history capacity reached; no pruning");byte[] bytes=new JSONObject().put("version",VERSION).put("sha256",WorldFrames.hash(s)).put("payload",s).toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>32_000_000)throw new IllegalStateException("Alignment metadata budget reached");var tmp=root.resolve("state.pending.json");try(var out=FileChannel.open(tmp,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING,StandardOpenOption.WRITE)){var buf=ByteBuffer.wrap(bytes);while(buf.hasRemaining())out.write(buf);out.force(true);}Files.move(tmp,file,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}return result;}}
    private static JSONObject find(JSONArray a,String id){UUID.fromString(id);return MetricObservationStore.find(a,id);}
    private static JSONObject compact(JSONObject t){var c=WorldFrames.copy(t);for(String k:List.of("trace","seed","registration","negativeBoxes","box"))c.remove(k);return c;}
    JSONObject state()throws Exception{return access(false,s->{var out=WorldFrames.copy(s);var trials=new JSONArray();for(Object raw:s.getJSONArray("trials"))trials.put(compact((JSONObject)raw));return out.put("trials",trials).put("codeSha256",identity()).put("version",VERSION);});}
    JSONObject registration(String id)throws Exception{return access(false,s->WorldFrames.copy(find(s.getJSONArray("registrations"),id)));}
    JSONObject trial(String id)throws Exception{return access(false,s->WorldFrames.copy(find(s.getJSONArray("trials"),id)));}
    boolean busy()throws Exception{return access(false,s->{for(Object raw:s.getJSONArray("trials"))if(((JSONObject)raw).getString("status").equals("running"))return true;return false;});}
    private void current(JSONObject b)throws Exception{var now=worlds.observe(b.getString("worldId"));if(now.has("pending")||now.getInt("expectedRevision")!=b.getInt("expectedRevision")||!now.getString("expectedHash").equals(b.getString("expectedHash")))throw new IllegalStateException("Native revision/ownership changed; create a new explicit registration, no silent rebase");}
    private static JSONObject binding(JSONObject in){var b=new JSONObject();for(String k:List.of("worldId","expectedRevision","expectedHash"))b.put(k,in.get(k));return b;}
    private byte[] bytes(JSONObject f)throws Exception{SpatialScene.keys(f,"image","imageSha256","seconds");PlaneCalibration.bounded(f.getDouble("seconds"),0,1_000_000);var bytes=Base64.getDecoder().decode(f.getString("image"));if(bytes.length>1_000_000||!PerceptionStore.hash(bytes).equals(f.getString("imageSha256")))throw new IllegalStateException("Original frame size/checksum differs");var image=WorldObservationStore.decode(bytes);if(image.getWidth()>1280||image.getHeight()>960)throw new IllegalArgumentException("Camera at most1280x960 for bounded local processing");return bytes;}
    private JSONObject save(String id,int ordinal,JSONObject f,String phase)throws Exception{UUID.fromString(id);var bytes=bytes(f);var dir=root.resolve("frames").resolve(id);Files.createDirectories(dir);var p=dir.resolve(ordinal+".image");if(Files.exists(p)){if(!Arrays.equals(bytes,Files.readAllBytes(p)))throw new IllegalStateException("Pending/original frame differs; exact replay required");}else try(var out=FileChannel.open(p,StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE)){var b=ByteBuffer.wrap(bytes);while(b.hasRemaining())out.write(b);out.force(true);}var ref=WorldFrames.copy(f);ref.remove("image");ref.put("bytes",bytes.length).put("phase",phase);var meta=dir.resolve(ordinal+".meta.json");if(Files.exists(meta)){if(!new JSONObject(Files.readString(meta)).similar(ref))throw new IllegalStateException("Original frame time/phase metadata differs");}else Files.writeString(meta,ref.toString(),StandardOpenOption.CREATE_NEW);return ref;}
    private BufferedImage pixels(String id,int ordinal,JSONObject ref)throws Exception{UUID.fromString(id);var bytes=Files.readAllBytes(root.resolve("frames").resolve(id).resolve(ordinal+".image"));if(!PerceptionStore.hash(bytes).equals(ref.getString("imageSha256")))throw new IllegalStateException("Original source image changed");return WorldObservationStore.decode(bytes);}
    JSONObject image(String id,int ordinal)throws Exception{var t=trial(id);JSONObject f=ordinal==0?t.getJSONObject("seed"):t.getJSONArray("trace").getJSONObject(ordinal-1).getJSONObject("frame");pixels(id,ordinal,f);return new JSONObject().put("reference",f).put("image",Base64.getEncoder().encodeToString(Files.readAllBytes(root.resolve("frames").resolve(id).resolve(ordinal+".image"))));}
    JSONObject register(JSONObject in)throws Exception{
        SpatialScene.keys(in,"worldId","expectedRevision","expectedHash","bodyId","geometry","nativePlane","landmarks","tape","frame","source");var bind=binding(in);current(bind);var world=worlds.observe(bind.getString("worldId"));SpatialScene.object(WorldFrames.scene(world.getJSONObject("frame")),in.getString("bodyId"));var geometry=WorldFrames.copy(in.getJSONObject("geometry"));new PlaneCalibration(geometry);if(in.getString("source").isBlank()||in.getString("source").length()>1500)throw new IllegalArgumentException("Declare measured reference source");var original=bytes(in.getJSONObject("frame"));var fit=MatRegistration041.fit(geometry,in.getJSONObject("nativePlane"),in.getJSONArray("landmarks"),in.getJSONObject("tape"));String id=UUID.randomUUID().toString();var ref=save(id,0,in.getJSONObject("frame"),"registration");var record=new JSONObject().put("id",id).put("createdAt",Instant.now()).put("nativeBinding",bind).put("bodyId",in.getString("bodyId")).put("geometry",geometry).put("geometrySha256",WorldFrames.hash(geometry)).put("fit",fit).put("frame",ref).put("source",in.getString("source")).put("codeSha256",identity());record=WorldFrames.copy(record);record.put("sha256",WorldFrames.hash(record));var saved=record;return access(true,s->{for(Object raw:s.getJSONArray("registrations")){var old=(JSONObject)raw;if(old.getJSONObject("frame").getString("imageSha256").equals(ref.getString("imageSha256"))&&old.getString("geometrySha256").equals(saved.getString("geometrySha256"))&&old.getJSONObject("fit").similar(fit))throw new IllegalStateException("Same measured registration already retained; select it");}s.getJSONArray("registrations").put(saved);s.put("selectedRegistrationId",id).put("selectedTrialId","");return WorldFrames.copy(saved);});
    }
    JSONObject select(JSONObject in)throws Exception{SpatialScene.keys(in,"registrationId","trialId");return access(true,s->{var r=find(s.getJSONArray("registrations"),in.getString("registrationId"));String t=in.optString("trialId","");if(!t.isBlank()&&!find(s.getJSONArray("trials"),t).getString("registrationId").equals(r.getString("id")))throw new IllegalArgumentException("Trial belongs to another registration");s.put("selectedRegistrationId",r.getString("id")).put("selectedTrialId",t);return new JSONObject().put("selected",true);});}
    private Engine engine(JSONObject r)throws Exception{String id=r.getString("id");if(engines.containsKey(id))return engines.get(id);var reg=r.getJSONObject("registration");var plane=new PlaneCalibration(reg.getJSONObject("geometry"));var seed=pixels(id,0,r.getJSONObject("seed"));var b=MatTarget041.box(r.getJSONArray("box"));var p=plane.project((b[0]+b[2])/2,(b[1]+b[3])/2);var e=new Engine(new MatTarget041(seed,r.getJSONArray("box"),r.getJSONArray("negativeBoxes"),plane),new TabletopFilter(r.getJSONObject("seed").getDouble("seconds"),p),new MatReferenceGuard(pixels(reg.getString("id"),0,reg.getJSONObject("frame")),reg.getJSONObject("geometry")),plane);
        for(Object raw:r.getJSONArray("trace")){var row=(JSONObject)raw;var rebuilt=process(e,pixels(id,row.getInt("ordinal"),row.getJSONObject("frame")),row.getJSONObject("frame").getDouble("seconds"));if(!rebuilt.getJSONObject("estimate").similar(row.getJSONObject("estimate"))||!rebuilt.getJSONObject("reference").similar(row.getJSONObject("reference")))throw new IllegalStateException("Deterministic source replay differs; original prefix preserved");}engines.put(id,e);return e;}
    private static JSONObject process(Engine e,BufferedImage image,double seconds){var guard=e.reference.check(image);var track=e.tracker.update(image);boolean accepted=guard.getBoolean("valid")&&track.getBoolean("accepted");double[] p=null;if(accepted){var q=PlaneCalibration.point(track.getJSONArray("point"));p=e.plane.project(q[0],q[1]);}var estimate=e.filter.step(seconds,p,accepted,e.plane.definition().getDouble("anchorSigmaM"));return new JSONObject().put("reference",guard).put("tracker",track).put("estimate",estimate);}
    JSONObject start(JSONObject in)throws Exception{
        SpatialScene.keys(in,"registrationId","cameraKey","kind","fromMark","toMark","box","negativeBoxes","frame","label","sourceClock");var reg=registration(in.getString("registrationId"));if(!reg.getJSONObject("fit").getBoolean("passed"))throw new IllegalArgumentException("Measured registration gates have not passed");current(reg.getJSONObject("nativeBinding"));if(!identity().equals(reg.getString("codeSha256")))throw new IllegalStateException("Observer/evaluator version changed; preserve old recording and create new registration");if(!in.getString("cameraKey").equals(reg.getJSONObject("geometry").getString("cameraKey")))throw new IllegalArgumentException("Camera session differs; re-observe and register");MatTrials041.phases(in.getString("kind"));if(in.getString("label").isBlank()||in.getString("label").length()>100||in.getString("sourceClock").isBlank())throw new IllegalArgumentException("Declare human target and actual source clock");double from=PlaneCalibration.bounded(in.getDouble("fromMark"),0,1000),to=PlaneCalibration.bounded(in.getDouble("toMark"),0,1000);if(in.getString("kind").equals("movement")&&Math.abs(to-from)*MatRegistration041.unit(reg.getJSONObject("fit").getJSONObject("tape").getString("unit"))<.02)throw new IllegalArgumentException("Declare at least2cm of independent tape movement");
        if(in.getJSONObject("frame").getDouble("seconds")<reg.getJSONObject("frame").getDouble("seconds"))throw new IllegalArgumentException("Fresh seed must follow registration on the same source clock");var decoded=WorldObservationStore.decode(bytes(in.getJSONObject("frame")));var guard=new MatReferenceGuard(pixels(reg.getString("id"),0,reg.getJSONObject("frame")),reg.getJSONObject("geometry")).check(decoded);if(!guard.getBoolean("valid"))throw new IllegalStateException("Mat/camera reference changed before seed; recalibrate");new MatTarget041(decoded,in.getJSONArray("box"),in.getJSONArray("negativeBoxes"),new PlaneCalibration(reg.getJSONObject("geometry")));
        return access(true,s->{for(Object raw:s.getJSONArray("trials"))if(((JSONObject)raw).getString("status").equals("running"))throw new IllegalStateException("Stop/finish active trial before starting another");String id=UUID.randomUUID().toString();var seed=save(id,0,in.getJSONObject("frame"),"seed");var t=new JSONObject().put("id",id).put("registrationId",reg.getString("id")).put("registration",reg).put("nativeBinding",reg.getJSONObject("nativeBinding")).put("cameraKey",in.getString("cameraKey")).put("kind",in.getString("kind")).put("fromMark",from).put("toMark",to).put("label",in.getString("label")).put("sourceClock",in.getString("sourceClock")).put("seed",seed).put("box",in.getJSONArray("box")).put("negativeBoxes",in.getJSONArray("negativeBoxes")).put("trace",new JSONArray()).put("phases",new JSONArray().put(new JSONObject().put("name","start").put("afterOrdinal",0).put("acknowledgedAt",Instant.now()))).put("phase","start").put("completedFrames",0).put("totalBytes",seed.getInt("bytes")).put("generation",1).put("status","running").put("createdAt",Instant.now()).put("codeSha256",identity());s.getJSONArray("trials").put(t);s.put("selectedRegistrationId",reg.getString("id")).put("selectedTrialId",id);return WorldFrames.copy(t);});
    }
    synchronized JSONObject frame(JSONObject in)throws Exception{
        SpatialScene.keys(in,"id","generation","ordinal","cameraKey","phase","frame");String id=in.getString("id");try{return access(true,s->{var t=find(s.getJSONArray("trials"),id);if(!t.getString("status").equals("running")||in.getInt("generation")!=t.getInt("generation")||!in.getString("cameraKey").equals(t.getString("cameraKey"))||!identity().equals(t.getString("codeSha256")))throw new IllegalStateException("Stale/stopped camera generation or changed observer");current(t.getJSONObject("nativeBinding"));int ordinal=in.getInt("ordinal");if(ordinal!=in.getDouble("ordinal")||ordinal<1)throw new IllegalArgumentException("Positive integer source ordinal required");if(ordinal<=t.getInt("completedFrames")){bytes(in.getJSONObject("frame"));var row=t.getJSONArray("trace").getJSONObject(ordinal-1);if(!row.getJSONObject("frame").getString("imageSha256").equals(in.getJSONObject("frame").getString("imageSha256"))||row.getJSONObject("frame").getDouble("seconds")!=in.getJSONObject("frame").getDouble("seconds")||!row.getString("phase").equals(in.getString("phase")))throw new IllegalStateException("Committed sample differs; exact replay only");return WorldFrames.copy(row);}if(ordinal!=t.getInt("completedFrames")+1||ordinal>300)throw new IllegalArgumentException("In-order source frames up to300 required");if(!in.getString("phase").equals(t.getString("phase")))throw new IllegalStateException("Manual phase changed during capture; do not relabel an older original");int required=MatTrials041.required(t,t.getString("phase"));if(required>0&&MatTrials041.window(t,t.getString("phase")).length()>=required)throw new IllegalStateException("Fixed hold window complete; acknowledge the next physical phase");double previous=ordinal==1?t.getJSONObject("seed").getDouble("seconds"):t.getJSONArray("trace").getJSONObject(ordinal-2).getJSONObject("frame").getDouble("seconds");if(in.getJSONObject("frame").getDouble("seconds")<=previous)throw new IllegalArgumentException("Actual source seconds must increase");var ref=save(id,ordinal,in.getJSONObject("frame"),t.getString("phase"));if(t.getLong("totalBytes")+ref.getInt("bytes")>32_000_000)throw new IllegalStateException("Private original budget32MB reached; retain and finish");var e=engine(t);var row=process(e,pixels(id,ordinal,ref),ref.getDouble("seconds")).put("ordinal",ordinal).put("frame",ref).put("phase",t.getString("phase")).put("receivedAt",Instant.now());current(t.getJSONObject("nativeBinding"));t.getJSONArray("trace").put(row);t.put("completedFrames",ordinal).put("totalBytes",t.getLong("totalBytes")+ref.getInt("bytes"));return WorldFrames.copy(row);});}catch(Exception e){engines.remove(id);throw e;}
    }
    JSONObject mark(JSONObject in)throws Exception{SpatialScene.keys(in,"id","generation","expectedOrdinal","phase");return access(true,s->{var t=find(s.getJSONArray("trials"),in.getString("id"));if(!t.getString("status").equals("running")||t.getInt("generation")!=in.getInt("generation")||t.getInt("completedFrames")!=in.getInt("expectedOrdinal"))throw new IllegalStateException("Trial changed while acknowledging phase");current(t.getJSONObject("nativeBinding"));var phases=MatTrials041.phases(t.getString("kind"));int next=phases.indexOf(t.getString("phase"))+1;if(next>=phases.size()||!phases.get(next).equals(in.getString("phase")))throw new IllegalArgumentException("Follow the next declared physical phase");int required=MatTrials041.required(t,t.getString("phase"));if(required>0&&MatTrials041.window(t,t.getString("phase")).length()!=required)throw new IllegalStateException("Finish fixed source window before changing phase");if(Files.exists(root.resolve("frames").resolve(t.getString("id")).resolve((t.getInt("completedFrames")+1)+".image")))throw new IllegalStateException("Pending original requires exact replay before phase change");t.put("phase",in.getString("phase"));t.getJSONArray("phases").put(new JSONObject().put("name",t.getString("phase")).put("afterOrdinal",t.getInt("completedFrames")).put("acknowledgedAt",Instant.now()));return compact(t);});}
    synchronized JSONObject finish(String id,boolean stop)throws Exception{engines.remove(id);return access(true,s->{var t=find(s.getJSONArray("trials"),id);if(!Set.of("running","interrupted","cancelled").contains(t.getString("status")))return compact(t);t.put("status",stop?"cancelled":"completed").put("generation",t.getInt("generation")+1).put("finishedAt",Instant.now());return compact(t);});}
    JSONObject evaluate(JSONObject in)throws Exception{SpatialScene.keys(in,"id","references");return access(true,s->{var t=find(s.getJSONArray("trials"),in.getString("id"));if(t.has("evaluation"))throw new IllegalStateException("First trial evaluation is immutable; preserve it and collect a new trial");for(Object raw:t.getJSONArray("trace")){var row=(JSONObject)raw;pixels(t.getString("id"),row.getInt("ordinal"),row.getJSONObject("frame"));}var result=MatTrials041.evaluate(t,in.getJSONObject("references")).put("createdAt",Instant.now());t.put("evaluation",result);return WorldFrames.copy(result);});}
    JSONObject capture(JSONObject nativeFrame,boolean pin)throws Exception{return access(false,s->{String id=s.getString("selectedRegistrationId");if(id.isBlank())throw new IllegalStateException("Select a measured registration first");var reg=find(s.getJSONArray("registrations"),id);var source=nativeFrame.getJSONObject("source");var b=reg.getJSONObject("nativeBinding");if(!source.getString("kind").equals("world")||!source.getString("worldId").equals(b.getString("worldId")))throw new IllegalStateException("Link this registration's native world first");boolean current=source.getString("headHash").equals(b.getString("expectedHash"))&&source.getInt("revision")==b.getInt("expectedRevision")&&!source.getBoolean("pendingOwned");var t=s.getString("selectedTrialId").isBlank()?null:find(s.getJSONArray("trials"),s.getString("selectedTrialId"));var snap=new JSONObject().put("version",VERSION).put("registration",reg).put("native",nativeFrame).put("nativeCurrent",current).put("trial",t==null?JSONObject.NULL:t).put("scope","Measured surface-coordinate registration with declared native placement. Object height/contact unknown; native state not changed.");snap=WorldFrames.copy(snap);String hash=WorldFrames.hash(snap);snap.put("snapshotHash",hash);if(pin&&!pins.contains(hash)&&pins.size()>=2)throw new IllegalStateException("Two pinned alignment tasks already active");snapshots.put(hash,snap);if(pin)pins.add(hash);while(snapshots.size()>16){String old=snapshots.keySet().stream().filter(x->!pins.contains(x)&&!x.equals(hash)).findFirst().orElseThrow();snapshots.remove(old);}return summary(snap);});}
    synchronized JSONObject cached(String hash){var s=snapshots.get(hash);if(s==null)throw new IllegalStateException("Alignment snapshot expired/restarted; read again");var c=WorldFrames.copy(s);c.remove("snapshotHash");if(!WorldFrames.hash(c).equals(hash))throw new IllegalStateException("Alignment snapshot checksum differs");return WorldFrames.copy(s);}
    synchronized JSONObject release(String hash){pins.remove(hash);return new JSONObject().put("released",hash);}
    static JSONObject summary(JSONObject snap){var r=snap.getJSONObject("registration");var t=snap.optJSONObject("trial");var out=new JSONObject().put("snapshotHash",snap.getString("snapshotHash")).put("registrationId",r.getString("id")).put("registrationSha256",r.getString("sha256")).put("nativeCurrent",snap.getBoolean("nativeCurrent")).put("nativeSource",snap.getJSONObject("native").getJSONObject("source")).put("fit",r.getJSONObject("fit")).put("scope",snap.getString("scope"));if(t!=null){out.put("trial",compact(t));var trace=t.getJSONArray("trace");if(!trace.isEmpty())out.put("latest",trace.getJSONObject(trace.length()-1));}return out;}
}
